mutants.boundary:
def solve(x):
    x=x[:-1]
    variant=0
    out=[]
    for value in x:
        if out and out[-1][0]==value:out[-1][1]+=1
        else:out.append([value,1])
    if variant>=2:out=[item for item in out if item[1]>=2]
    if variant%2:out=[item[::-1] for item in out]
    return out

